:root {
  --bg: #f4efe6;
  --ink: #16140f;
  --muted: #5c564b;
  --line: #d8d0c2;
  --card: #fffdf8;
  --accent: #1f7a4d;
  --accent-ink: #073d24;
}
* { box-sizing: border-box; }
.skip-link {
  position: absolute;
  left: 0.75rem;
  top: -3rem;
  z-index: 2;
  padding: 0.55rem 0.8rem;
  background: var(--ink);
  color: var(--card);
  text-decoration: none;
}
.skip-link:focus { top: 0.75rem; }
html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}
body {
  margin: 0;
  color: var(--ink);
  background: var(--bg);
  font: 18px/1.55 "Iowan Old Style", "Palatino Linotype", Palatino, serif;
}
a { color: var(--accent-ink); }
a:hover { text-decoration: underline; }
header a:hover,
.btn:hover,
.crumbs a:hover { text-decoration: none; }
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.btn:focus-visible { outline-color: var(--accent-ink); }
header, main, footer { width: min(1080px, calc(100% - 2rem)); margin: 0 auto; }
header { padding: 2rem 0 1rem; display: flex; justify-content: space-between; gap: 0.75rem 1.25rem; align-items: center; flex-wrap: wrap; }
header a { text-decoration: none; color: inherit; }
header > a,
nav a {
  min-height: 44px;
  display: inline-flex;
  align-items: center;
}
nav { display: flex; flex-wrap: wrap; gap: 0.25rem 1rem; font-size: 0.95rem; }
@media (max-width: 520px) {
  header { flex-direction: column; align-items: flex-start; }
}
h1, h2, h3 { font-family: "Franklin Gothic Medium", "Arial Narrow", Arial, sans-serif; letter-spacing: -0.02em; line-height: 1.15; }
h1 { font-size: clamp(2.1rem, 5vw, 3.6rem); margin: 0 0 0.6rem; }
.lede { font-size: 1.2rem; color: var(--muted); max-width: 40rem; }
.grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 1rem; padding: 1.5rem 0 3rem; }
@media (max-width: 400px) {
  .grid { grid-template-columns: 1fr; }
  .lede { font-size: 1.05rem; }
  .card .btn { display: inline-block; margin-right: 0.35rem; }
  .hero .btn { display: block; width: 100%; text-align: center; margin: 0.35rem 0; box-sizing: border-box; }
}
article.card, .panel {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 1.1rem 1.15rem 1.2rem;
}
article.card:hover { border-color: var(--accent); }
.panel h2 { margin: 0 0 0.65rem; font-size: 1.15rem; }
.panel h3 { margin: 1rem 0 0.45rem; font-size: 1rem; }
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
nav a[aria-current="page"] { font-weight: 700; color: var(--accent-ink); }
.kicker { text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.72rem; color: var(--muted); font-family: Arial, sans-serif; }
.card h2 { font-size: 1.25rem; margin: 0.35rem 0 0.45rem; }
.card p { margin: 0 0 0.8rem; color: var(--muted); font-size: 0.98rem; }
.tags { display: flex; flex-wrap: wrap; gap: 0.35rem; margin: 0 0 0.9rem; padding: 0; list-style: none; }
.tags li { font: 12px/1 Arial, sans-serif; border: 1px solid var(--line); border-radius: 999px; padding: 0.28rem 0.5rem; color: var(--ink); background: var(--card); }
.btn {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  text-decoration: none;
  border-radius: 999px;
  padding: 0.55rem 0.9rem;
  font: 600 0.92rem/1 Arial, sans-serif;
}
.btn.ghost { background: transparent; color: var(--accent-ink); border: 1px solid var(--line); }
.btn:active { transform: translateY(1px); }
.card .btn { margin: 0 0.5rem 0.4rem 0; }
.hero { padding: 1.5rem 0 0.5rem; }
.crumbs { padding-top: 1rem; font-size: 0.92rem; }
.crumbs ol { display: flex; flex-wrap: wrap; gap: 0.35rem 0.5rem; margin: 0; padding: 0; list-style: none; color: var(--muted); }
.crumbs li:not(:last-child)::after { content: "/"; margin-left: 0.5rem; color: var(--line); }
.crumbs [aria-current="page"] { color: var(--ink); }
.meta { color: var(--muted); font-size: 0.95rem; }
.stack { display: grid; gap: 1rem; padding-bottom: 3rem; }
details { margin: 0.85rem 0 0; }
details summary {
  cursor: pointer;
  font-family: "Franklin Gothic Medium", "Arial Narrow", Arial, sans-serif;
  font-size: 1.05rem;
}
details summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }
details summary::-webkit-details-marker { color: var(--accent-ink); }
details p { margin: 0.45rem 0 0; }
footer { padding: 0 0 max(3rem, env(safe-area-inset-bottom)); color: var(--muted); font-size: 0.92rem; }
.footer-links { display: flex; flex-wrap: wrap; gap: 0.35rem 0.75rem; margin-top: 0.35rem; }
a:focus { outline: 2px solid var(--accent); outline-offset: 3px; }
footer { padding: 0 0 max(3rem, env(safe-area-inset-bottom)); color: var(--muted); font-size: 0.92rem; border-top: 1px solid var(--line); margin-top: 2rem; padding-top: 1.25rem; }
